"""Chroma retrieval with query embeddings generated by the isolated service."""
import chromadb
from src.utils.logger import logger
from src.config.settings import settings
from src.rag.embedding_client import embed_texts

class RetrievalEngine:
    def __init__(self):
        self.client = chromadb.PersistentClient(path=str(settings.VECTOR_DB_PATH))
        self.collection = None

    def get_collection(self):
        if self.collection is None:
            logger.info("Connecting to ChromaDB collection hsbc_kpis")
            try:
                self.collection = self.client.get_collection("hsbc_kpis")
            except Exception as exc:
                raise RuntimeError(f"Chroma collection 'hsbc_kpis' is unavailable at {settings.VECTOR_DB_PATH}: {exc}") from exc
        return self.collection

    def search(self, query, top_k=None):
        query = str(query or "").strip()
        if not query:
            return []
        n = max(1, int(top_k or settings.TOP_K))
        vector = embed_texts([query])[0]
        collection = self.get_collection()
        n = min(n, collection.count())
        if n <= 0:
            return []
        result = collection.query(query_embeddings=[vector], n_results=n)
        docs = (result.get("documents") or [[]])[0] or []
        metas = (result.get("metadatas") or [[]])[0] or []
        distances = (result.get("distances") or [[]])[0] or []
        matches = []
        for i, document in enumerate(docs):
            matches.append({"text": document, "metadata": metas[i] if i < len(metas) else {}, "distance": distances[i] if i < len(distances) else None})
        logger.info("%d documents retrieved", len(matches))
        return matches

_engine = None

def retrieve(question: str, top_k=None):
    global _engine
    if _engine is None:
        _engine = RetrievalEngine()
    return _engine.search(question, top_k)
